// Generates src/manifest.generated.ts from schema/manifest.v1.schema.json, the source of the manifest contract.
// Usage: node scripts/generate-manifest.ts   writes src/manifest.generated.ts
//        imported by tools/checks/repo-check.ts to detect a stale generated file.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile, type JSONSchema } from 'json-schema-to-typescript';
import { format, resolveConfig } from 'prettier';

const packageRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
export const schemaPath = join(packageRoot, 'schema', 'manifest.v1.schema.json');
export const generatedPath = join(packageRoot, 'src', 'manifest.generated.ts');

const HEADER =
  '// Generated by sdk/scripts/generate-manifest.ts from sdk/schema/manifest.v1.schema.json. Do not edit.';

/** Returns the content of src/manifest.generated.ts. */
export async function generate(): Promise<string> {
  const schema = JSON.parse(readFileSync(schemaPath, 'utf8')) as JSONSchema;
  const source = await compile(schema, 'AppManifest', {
    bannerComment: HEADER,
    additionalProperties: false,
    format: false,
    unreachableDefinitions: false,
    strictIndexSignatures: false,
    ignoreMinAndMaxItems: true,
  });
  const options = await resolveConfig(generatedPath);
  return format(source, { ...options, filepath: generatedPath });
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(generatedPath, await generate());
}
